package com.playeverywhere.photonbeat;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.hardware.camera2.*;import android.media.projection.*;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 Handler h=new Handler(); LinearLayout root; TextView status; Switch flash; SeekBar gain; CameraManager cam; String camera; boolean torch; long last; float r,g,b,avg; boolean mic;
 public void onCreate(Bundle s){super.onCreate(s);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(32,48,32,32);root.setGravity(Gravity.CENTER);root.setBackgroundColor(Color.BLACK);setContentView(root);status=new TextView(this);status.setText("PHOTON BEAT");status.setTextSize(24);status.setTextColor(-1);root.addView(status);button("Медиапоток",()->start(false));button("Микрофон",()->start(true));button("Стоп",()->{stopService(new Intent(this,CaptureService.class));setTorch(false);});flash=new Switch(this);flash.setText("Фонарик (до 2 вспышек/с)");root.addView(flash);flash.setOnCheckedChangeListener((v,on)->{if(!on)setTorch(false);else if(checkSelfPermission(android.Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.CAMERA},2);});gain=new SeekBar(this);gain.setMax(100);gain.setProgress(50);root.addView(gain,new LinearLayout.LayoutParams(-1,-2));cam=getSystemService(CameraManager.class);try{for(String id:cam.getCameraIdList())if(Boolean.TRUE.equals(cam.getCameraCharacteristics(id).get(CameraCharacteristics.FLASH_INFO_AVAILABLE))){camera=id;break;}}catch(Exception e){}h.post(tick);}
 void button(String t,Runnable a){Button v=new Button(this);v.setText(t);v.setOnClickListener(w->a.run());root.addView(v);}
 void start(boolean m){mic=m;if(CaptureService.running){Toast.makeText(this,"Сначала нажмите Стоп",0).show();return;}if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},1);return;}if(m)startForegroundService(new Intent(this,CaptureService.class).putExtra("mic",true));else startActivityForResult(getSystemService(MediaProjectionManager.class).createScreenCaptureIntent(),3);}
 public void onRequestPermissionsResult(int q,String[] p,int[] a){super.onRequestPermissionsResult(q,p,a);if(q==1&&a.length>0&&a[0]==0)start(mic);if(q==2&&(a.length==0||a[0]!=0))flash.setChecked(false);}
 protected void onActivityResult(int q,int c,Intent d){super.onActivityResult(q,c,d);if(q==3&&c==RESULT_OK)startForegroundService(new Intent(this,CaptureService.class).putExtra("result",c).putExtra("data",d));}
 void setTorch(boolean v){if(camera==null||torch==v)return;try{cam.setTorchMode(camera,v);torch=v;}catch(Exception e){if(v)flash.setChecked(false);}}
 int channel(float v){return (int)Math.min(180,Math.max(0,v));}
 Runnable tick=new Runnable(){public void run(){float k=5+gain.getProgress()/3f;float lo=CaptureService.bass,mi=CaptureService.mid,hi=CaptureService.high;r=.85f*r+.15f*channel(lo*k*255);g=.85f*g+.15f*channel(mi*k*255);b=.85f*b+.15f*channel(hi*k*510);root.setBackgroundColor(Color.rgb(channel(r),channel(g),channel(b)));long now=SystemClock.elapsedRealtime();if(torch&&now-last>=90)setTorch(false);if(CaptureService.running&&flash.isChecked()&&hasWindowFocus()&&now-last>=550&&lo>Math.max(.018f,avg*1.6f)){last=now;setTorch(true);}avg=.94f*avg+.06f*lo;status.setText(CaptureService.running?"PHOTON BEAT\nАнализ звука":"PHOTON BEAT\nВыберите источник звука");h.postDelayed(this,40);}};
 protected void onPause(){super.onPause();setTorch(false);}protected void onDestroy(){h.removeCallbacks(tick);setTorch(false);stopService(new Intent(this,CaptureService.class));super.onDestroy();}
}